import{_ as o,o as a,c as t,a6 as r}from"./chunks/framework.CKIbuWFA.js";const b=JSON.parse('{"title":"Desarrollar TikTools","description":"","frontmatter":{"title":"Desarrollar TikTools","docId":"developer.overview","translationKey":"developer.overview","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1ee65a70172f8154eeaf60fb1a3069192769582a4ef264426d0aefaf346e8003","translationRevision":"dce8233794e6aa3dcf805b91d9f881a553106387596b68b46a74270f571e9ff8","order":0},"headers":[],"relativePath":"es/developer/index.md","filePath":"es/developer/index.md","lastUpdated":1794611623000}'),i={name:"es/developer/index.md"};function s(n,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="develop-tiktools" tabindex="-1">Desarrollar TikTools <a class="header-anchor" href="#develop-tiktools" aria-label="Permalink to &quot;Desarrollar TikTools {#develop-tiktools}&quot;">​</a></h1><p>TikTools mantiene un único AppCore nativo detrás de operaciones de control tipadas. Vue representa las interfaces de escritorio, navegador local y controller; Winit/Wry administra las ventanas nativas. CLI y SDK utilizan las mismas operaciones. Empieza por la <a href="./setup.html">preparación de desarrollo</a> y elige el ciclo mínimo que cubra tu cambio.</p><h2 id="choose-an-entry-point" tabindex="-1">Elige una entrada <a class="header-anchor" href="#choose-an-entry-point" aria-label="Permalink to &quot;Elige una entrada {#choose-an-entry-point}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trabajo</th><th>Entrada</th><th>Qué comprueba</th></tr></thead><tbody><tr><td>Componentes Vue y stores</td><td>Vite, Vitest y ControlClient inyectado</td><td>Comportamiento de interfaz; no valida ventanas nativas.</td></tr><tr><td>Integración de escritorio</td><td><code>bun run start</code></td><td>WebView de desarrollo e integración IPC.</td></tr><tr><td>Servicios nativos</td><td>Tests Cargo enfocados</td><td>Contratos del núcleo, persistencia y servicios.</td></tr><tr><td>Acceso en navegador local</td><td><code>bun run dev</code></td><td>Host nativo, adaptador local y Vite con emparejamiento.</td></tr><tr><td>Documentación</td><td><code>bun scripts/task.ts docs dev</code></td><td>Markdown y build aislado de VitePress.</td></tr><tr><td>Demo pública</td><td>Entrada propia y transporte simulado</td><td>Escenarios ficticios deterministas, no servicios externos.</td></tr></tbody></table><h2 id="source-ownership" tabindex="-1">Responsabilidad del código <a class="header-anchor" href="#source-ownership" aria-label="Permalink to &quot;Responsabilidad del código {#source-ownership}&quot;">​</a></h2><ul><li><code>crates/tiktools-core</code>: servicios, operaciones y SQLite. No depende de una WebView.</li><li><code>crates/tiktools-control-api</code>: registro, JSON-RPC, IPC y descubrimiento.</li><li><code>crates/tiktools-desktop</code>: Winit/Wry, puente del hilo de interfaz, ciclo de vida y recursos empaquetados.</li><li><code>src/web/app</code>: arranque, router y shell. <code>pages</code> compone <code>widgets</code> y <code>features</code>; <code>entities</code> contiene stores y contratos de dominio; <code>shared</code> reúne interfaz e infraestructura reutilizables.</li><li><code>src/automation/contracts/generated</code>: contratos de eventos versionados para el frontend, generados desde Rust. No vuelvas a escribir esos schemas en la demo o las guías.</li><li><code>packages</code>: SDK y componentes TypeScript existentes para plugins. Sus implementaciones viven en el repositorio externo de plugins.</li></ul><h2 id="contribution-boundary" tabindex="-1">Límites de contribución <a class="header-anchor" href="#contribution-boundary" aria-label="Permalink to &quot;Límites de contribución {#contribution-boundary}&quot;">​</a></h2><p>Mantén explícitas las entradas nativa, de navegador local, controller remoto y demo. La ausencia del host nativo debe producir un error en una entrada real; nunca debe activar un mock silenciosamente. Libera listeners, suscripciones y temporizadores con su scope propietario. Conserva los lockfiles de Rust/Bun y los checks obligatorios de CI.</p><p>La instalación para usuarios pertenece a su <a href="./../user/installation.html">guía</a>. Estos checks de desarrollo no prueban por sí solos conectividad real con TikTok, representación en OBS, compatibilidad de la WebView nativa o colaboración entre dos equipos.</p>',9)])])}const m=o(i,[["render",s]]);export{b as __pageData,m as default};
